.app {
  min-height: 100vh;
  padding: 22px 18px 36px;
  background: linear-gradient(140deg, #25f4ee 0%, #009995 55%, #fe2c3a 100%);
  gap: 18px;
  display: flex;
  flex-direction: column;
  align-items: center;
}

.hero {
  align-items: center;
  display: flex;
  flex-direction: column;
  gap: 12px;
  text-align: center;
  width: 100%;
  max-width: 720px;
  color: #ffffff;
  margin-bottom: 50px;
}

.eyebrow {
  padding: 6px 12px;
  border: 1px solid rgba(255, 255, 255, 0.35);
  border-radius: 999px;
  background: rgba(0, 153, 149, 0.25);
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.4px;
  color: #ffffff;
}

.logo {
  width: 104px;
  height: 104px;
  border-radius: 28px;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.14);
  background: rgba(255, 255, 255, 0.1);
}

.title {
  font-size: 22px;
  font-weight: 800;
  letter-spacing: 0.2px;
}

.subtitle {
  font-size: 14px;
  line-height: 20px;
  color: #e6fbff;
}

.card {
  width: 100%;
  max-width: 720px;
  background: rgba(255, 255, 255, 0.96);
  border: 1px solid #b7f2f0;
  border-radius: 16px;
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.12);
  padding: 16px;
  gap: 12px;
  display: flex;
  flex-direction: column;
}

.card__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
